def is_not_prime(n):
    """
    Return True if n is NOT a prime number, False if n is prime.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(nums, n):
    """
    Find the n largest integers from a given list of numbers using heap queue algorithm.
    """
    return heapq.nlargest(n, nums)

def differ_At_One_Bit_Pos(a, b):
    x = a ^ b
    return x != 0 and (x & (x - 1)) == 0

def find_Rotations(s):
    n = len(s)
    s1 = s + s
    for i in range(1, n + 1):
        substring = s1[i: i + n]
        if s == substring:
            return i
    return n

def remove_Occ(s, ch):
    s = list(s)
    for i in range(len(s)):
        if s[i] == ch:
            del s[i]
            break
    for i in range(len(s) - 1, -1, -1):
        if s[i] == ch:
            del s[i]
            break
    return ''.join(s)

def is_woodall(num):
    """
    Check if a number is a Woodall number.

    A Woodall number has the form: n * 2^n - 1 for some positive integer n.

    Returns True if `num` is a Woodall number, False otherwise.
    """
    if num < 1:
        return False

    n = 1
    while True:
        value = n * (2 ** n) - 1
        if value == num:
            return True
        if value > num:
            return False
        n += 1

def check(n):
    reverse_n = int(str(n)[::-1])
    return n == 2 * reverse_n - 1

def max_difference(pairs):
    """
    Given a list of pairs/tuples, compute the absolute difference between
    the two elements of each pair, and return the maximum such difference.

    Example:
        max_difference([(1, 5), (3, 3), (10, 2)]) -> 8
    """
    if not pairs:
        return None

    return max(abs(a - b) for a, b in pairs)

def is_Monotonic(A):
    return (all(A[i] <= A[i + 1] for i in range(len(A) - 1)) or
            all(A[i] >= A[i + 1] for i in range(len(A) - 1)))
